from datetime import datetime
from logging import config  # noqa: F401
import logging
import sys
import atexit
from taf.gnb.oam.ne3s.ws.package import SoftwarePackage
from taf.gnb.oam.ne3s.ws.provider import NE3SProvider
from taf.gnb.oam.ne3s.ws.components.exceptions import OperationTimeout, OperationFailed
from taf.gnb.oam.ne3s.ws.components.connection.teardown import teardown_all_servers


class Timeout(Exception):
    pass


class ProvisioningFailed(Exception):
    pass


class NE3SClient(object):
    LOGGING_CONFIG = {
        'version': 1,
        'disable_existing_loggers': False,
        'formatters': {
            'verbose': {
                'format': '%(asctime)s %(levelname)s %(module)s %(process)d %(thread)d %(message)s'
            },
            'simple': {
                'format': '%(asctime)s %(levelname)s %(message)s'
            },
        },
        'handlers': {
            'console': {
                'level': 'INFO',
                'class': 'logging.StreamHandler',
                'formatter': 'simple',
                'stream': sys.stdout
            },
        },
        'loggers': {
            'taf.gnb.oam.ne3s.ws.logger': {
                'handlers': ['console'],
                'level': 'DEBUG',
            }
        }
    }

    def __init__(self,
                 address,
                 port=None,
                 username=None,
                 password=None,
                 netact_server_address=None,
                 netact_server_port=None,
                 manager_id=None,
                 name=None,
                 debug=False,
                 debug_log_path=None,
                 netact_version=None):

        self.configure_logging(debug, debug_log_path)

        self.interface = NE3SProvider.provide_interface(
            address=address,
            port=port,
            username=username,
            password=password,
            netact_server_address=netact_server_address,
            netact_server_port=netact_server_port,
            manager_id=manager_id,
            name=name,
            netact_version=netact_version
        )

    @classmethod
    def configure_logging(cls, debug, debug_log_path):
        if debug is True:
            debug_handler = {
                'level': 'DEBUG',
                'class': 'logging.FileHandler',
                'mode': 'w',
                'formatter': 'verbose',
                'filename': 'taf_ne3s_ws_debug-%Y-%m-%d_%H:%M:%S.%f.log'
            }

            log_path = datetime.strftime(datetime.now(),
                                         debug_handler.get('filename'))
            debug_log_path = debug_log_path or log_path
            debug_handler['filename'] = debug_log_path

            cls.LOGGING_CONFIG['handlers']['ws_debug'] = debug_handler
            cls.LOGGING_CONFIG['loggers']['taf.gnb.oam.ne3s.ws.logger']['handlers'].append('ws_debug')

        logging.config.dictConfig(cls.LOGGING_CONFIG)
        logging.raiseExceptions = False

    def connect(self):
        self.interface.connection.connect()

    def update_software(self,
                        bts_sw_path,
                        adaptation_version=None,
                        timeout=1200):
        """
        Method starts 2 processes: server process and configuration
        upload triggering process.

        Then the method waits until it receives notification
        indicating either the successful completion of the update or an error.

        :param bts_sw_path: path to the SW package in .zip format
        :param timeout: how many seconds to wait for the SW Update to finish
        :param adaptation_version: defaults to "MRBTS-1900"
        """
        package = SoftwarePackage(bts_sw_path)
        package_version, cbts_package_version = package.get_software_versions()
        try:
            active_sw_version = self.interface.swm.update_software(
                bts_sw_path=package.path,
                package_version=package_version,
                adaptation_version=adaptation_version,
                timeout=timeout)

        except OperationTimeout as e:
            active_sw_version = self.get_active_software_version()
            if active_sw_version != cbts_package_version:
                err_msg = "After timeout have passed, the NE active sw version is {} instead of requested {}, Error: {}"
                raise OperationFailed(err_msg.format(active_sw_version, cbts_package_version, e))
        return active_sw_version

    def get_current_plan(self, file_path, timeout=120):
        """
        Saves Current Plan of connected NodeB to file under file_path

        :param str file_path: path where current plan will be saved
        :param float timeout: timeout in seconds for keyword execution, defaults to 120
        :raises OperationTimeout: when no information was provided by the Node B
        :raises OperationFailed: when error occurred and no information could be requested
        """
        current_plan = self.interface.cm.get_current_plan(timeout=timeout)
        with open(file_path, 'wb') as f:
            f.write(current_plan)

    def get_active_software_version(self, timeout=20):
        """
        Get Active Partition Software Version of connected NodeB

        :param float timeout: timeout in seconds for keyword execution, defaults to 20
        :raises OperationTimeout: when no information was provided by the Node B
        :raises OperationFailed: when error occurred and no information could be requested
        """
        return self.interface.cm.get_active_software_version(timeout=timeout)

    def set_managed_object_parameter(self, class_name, dist_name, version_name, param_changes, timeout=720.0):
        return self.interface.cm.set_managed_object_parameter(class_name, dist_name, version_name,
                                                              param_changes, timeout)

    def set_parameter_by_scf(self, scf_path, timeout=720.0):
        with open(scf_path, 'rb') as f:
            scf_data = f.read()
        return self.interface.cm.set_parameter_by_scf(scf_data, timeout)

    def get_active_faults(self, timeout=30):
        """
        Gets active faults
        :param float timeout: timeout for getting notification from server
        :return: list with alarms
        """
        return self.interface.fm.get_active_faults(timeout=timeout)

    def get_audit_trail_logs(
            self,
            destination_path,
            adaptation_version,
            logs_age_in_seconds,
            timeout=600):
        """
        Saves audit trail logs in given path
        :param str destination_path: ATL will be saved to this path
        :param str adaptation_version: defaults to "MRBTS-1900"
        :param float logs_age_in_seconds: start collecting logs from specified time difference in past (in seconds)
        :param float timeout: timeout for getting notification from server, defaults to 600 seconds
        """
        audit_trail_logs = self.interface.atl.get_audit_trail_logs(
            adaptation_version=adaptation_version,
            logs_age_in_seconds=logs_age_in_seconds,
            timeout=timeout)

        with open(destination_path, 'wb') as f:
            f.write(audit_trail_logs)

    def activate_pm_reporting(self, class_name, dist_name, version_name, collection_interval,
                              reporting_interval, timeout=300.0):
        pm_measurement_params = self.interface.pm.prepare_params_for_pm_measurement(collection_interval,
                                                                                    reporting_interval)
        self.interface.pm.activate_pm_collection_stream()
        self.set_managed_object_parameter(class_name=class_name,
                                          dist_name=dist_name,
                                          version_name=version_name,
                                          param_changes=pm_measurement_params,
                                          timeout=timeout)

    def fetch_latest_pm_report(self, pm_file_path, timeout=720.0):
        pm_content = self.interface.pm.fetch_latest_report(timeout)
        with open(pm_file_path, 'wb') as f:
            f.write(pm_content)

    def install_certificate(self, cert_dist_name, path_to_cert, timeout=400):
        """
        Installs certificate on BTS.

        :param str cert_dist_name: Dist name where certificate should be installed.
        :param str path_to_cert: Path to a local file that contains the certificate.
        :param float timeout: timeout for installing certificate on BTS, defaults to 400.
        """
        return self.interface.cert.install_cert(cert_dist_name=cert_dist_name,
                                                path_to_cert=path_to_cert,
                                                timeout=timeout)

    def delete_certificate(self, cert_dist_name, cert_fingerprint, timeout=200):
        """
        Removes certificate by provided fingerprint.

        :param str cert_dist_name: Dist name from which the certificate should be removed.
        :param str cert_fingerprint: Fingerprint needed to identify proper certificate.
        :param float timeout: timeout for removing certificate on BTS, defaults to 200.
        """
        return self.interface.cert.delete_cert(cert_dist_name=cert_dist_name,
                                               cert_fingerprint=cert_fingerprint,
                                               timeout=timeout)

    def initialize_certificate(self, dist_name, server_type=None, timeout=400):
        """
        Initialize CMP on BTS.

        :param str dist_name: Dist name of the certificate, e.g.: "MRBTS-50243/CERTH-1/CMP-1".
        :param str server_type: Certificate type, allowed values: ``RSA`` or ``ECDSA``.
            ``None`` is set by default, means that ``server_type`` will not be set in order
            to keep backward compatibility with the older SW releases that doesn't support it.
        :param float timeout: timeout for the operation, defaults to 400.
        """
        return self.interface.cert.initialize_certificate(dist_name=dist_name, timeout=timeout, server_type=server_type)

    def update_certificate(self, dist_name, server_type=None, timeout=400):
        """
        Update CMP key on BTS.

        :param str dist_name: Dist name of the certificate, e.g.: "MRBTS-50243/CERTH-1/CMP-1".
        :param str server_type: Certificate type, allowed values: ``RSA`` or ``ECDSA``.
            ``None`` is set by default, means that ``server_type`` will not be set in order
            to keep backward compatibility with the older SW releases that doesn't support it.
        :param float timeout: timeout for the operation, defaults to 400.
        """
        return self.interface.cert.update_certificate(dist_name=dist_name, timeout=timeout, server_type=server_type)

    def update_certificate_revocation_list(self, dist_name, timeout=400):
        """
        Update certificate revocation list on BTS.

        :param str dist_name: Dist name of the CRL, e.g.: "MRBTS-50243/CERTH-1/CRLH-1".
        :param float timeout: timeout for the operation, defaults to 400.
        """
        return self.interface.cert.update_certificate_revocation_list(dist_name=dist_name, timeout=timeout)

    def configure_cmp_server(self, dist_name, psk, ref_number, server_type=None, timeout=400):
        """
        Add pre-shared key and reference number to CMP settings.

        :param str dist_name: Dist name of the CRLH, e.g.: "MRBTS-50243/CERTH-1/CRLH-1".
        :param str psk: pre-shared key.
        :param int ref_number: reference number
        :param str server_type: Certificate type, allowed values: ``RSA`` or ``ECDSA``.
            ``None`` is set by default, means that ``server_type`` will not be set in order
            to keep backward compatibility with the older SW releases that doesn't support it.
        :param float timeout: timeout for the operation, defaults to 400.
        :param str connection: Alias of connection, if not given default connection used.
        """
        return self.interface.cert.configure_cmp_server(dist_name=dist_name, pre_shared_key=psk,
                                                        reference_number=ref_number, timeout=timeout,
                                                        server_type=server_type)

    def set_local_account(self, adaptation_version, user_type, username, password, timeout=400):

        """
        Set arbitrary local account's name and password

        :param str adaptation_version: eg. "MRBTS-50211"
        :param str user_type: eg. "BTSApplication"
        :param str username:
        :param str password:
        :param float timeout: timeout for the operation, defaults to 400.
        """
        return self.interface.um.set_local_account(adaptation_version, user_type, username, password, timeout)

    def unregister(self):
        self.interface.connection.unregister()
        self.interface.disconnect()

    def teardown_all(self):
        teardown_all_servers()

    def __del__(self):
        self.teardown_all()


NE3SClient.configure_logging(debug=False, debug_log_path=None)
atexit.register(teardown_all_servers)
